From 6c492291c669585c4edcda8154b1273f8110d638 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 19:06:00 +0100
Subject: [PATCH] wayland: let plasma shell surfaces exclude themselves from
 capture

Only window rules, the window menu and the task manager could hide a
window from screen capture, so shell surfaces like notification popups
couldn't opt out. Implement set_exclude_from_capture from plasma-shell v9.

BUG: 528880
---
 src/wayland/plasmashell.cpp | 19 ++++++++++++++++++-
 src/wayland/plasmashell.h   | 10 ++++++++++
 src/xdgshellwindow.cpp      |  7 +++++++
 3 files changed, 35 insertions(+), 1 deletion(-)

diff --git a/src/wayland/plasmashell.cpp b/src/wayland/plasmashell.cpp
index 51d34a5755..40988d78f4 100644
--- a/src/wayland/plasmashell.cpp
+++ b/src/wayland/plasmashell.cpp
@@ -16,7 +16,7 @@
 namespace KWin
 {

-static const quint32 s_version = 8;
+static const quint32 s_version = 9;
 static QList<PlasmaShellSurfaceInterface *> s_shellSurfaces;

 class PlasmaShellSurfaceCommit : public SurfaceAttachedState<PlasmaShellSurfaceCommit>
@@ -55,6 +55,7 @@ public:
     PlasmaShellSurfaceInterface::PanelBehavior m_panelBehavior = PlasmaShellSurfaceInterface::PanelBehavior::AlwaysVisible;
     bool m_skipTaskbar = false;
     bool m_skipSwitcher = false;
+    bool m_excludeFromCapture = false;
     bool m_panelTakesFocus = false;
     bool m_openUnderCursorRequested = false;

@@ -71,6 +72,7 @@ private:
     void org_kde_plasma_surface_set_panel_takes_focus(Resource *resource, uint32_t takes_focus) override;
     void org_kde_plasma_surface_set_skip_switcher(Resource *resource, uint32_t skip) override;
     void org_kde_plasma_surface_open_under_cursor(Resource *resource) override;
+    void org_kde_plasma_surface_set_exclude_from_capture(Resource *resource, uint32_t exclude) override;
 };

 PlasmaShellInterface::PlasmaShellInterface(Display *display, QObject *parent)
@@ -249,6 +251,16 @@ void PlasmaShellSurfaceInterfacePrivate::org_kde_plasma_surface_set_skip_switche
     Q_EMIT q->skipSwitcherChanged();
 }

+void PlasmaShellSurfaceInterfacePrivate::org_kde_plasma_surface_set_exclude_from_capture(Resource *resource, uint32_t exclude)
+{
+    const bool newExcludeFromCapture = bool(exclude);
+    if (m_excludeFromCapture == newExcludeFromCapture) {
+        return;
+    }
+    m_excludeFromCapture = newExcludeFromCapture;
+    Q_EMIT q->excludeFromCaptureChanged();
+}
+
 void PlasmaShellSurfaceInterfacePrivate::org_kde_plasma_surface_panel_auto_hide_hide(Resource *resource)
 {
     if (m_role != PlasmaShellSurfaceInterface::Role::Panel
@@ -313,6 +325,11 @@ bool PlasmaShellSurfaceInterface::skipSwitcher() const
     return d->m_skipSwitcher;
 }

+bool PlasmaShellSurfaceInterface::excludeFromCapture() const
+{
+    return d->m_excludeFromCapture;
+}
+
 void PlasmaShellSurfaceInterface::hideAutoHidingPanel()
 {
     d->send_auto_hidden_panel_hidden();
diff --git a/src/wayland/plasmashell.h b/src/wayland/plasmashell.h
index d62d3272b8..4eed0711fe 100644
--- a/src/wayland/plasmashell.h
+++ b/src/wayland/plasmashell.h
@@ -131,6 +131,12 @@ public:
      */
     bool skipSwitcher() const;

+    /**
+     * @returns true if this window doesn't want to be visible
+     * in screen captures
+     */
+    bool excludeFromCapture() const;
+
     /**
      * Informs the PlasmaShellSurfaceInterface that the auto-hiding panel got hidden.
      * Once it is shown again the method {@link showAutoHidingPanel} should be used.
@@ -194,6 +200,10 @@ Q_SIGNALS:
      * A change in the skip switcher property has been requested
      */
     void skipSwitcherChanged();
+    /**
+     * A change in the exclude from capture property has been requested
+     */
+    void excludeFromCaptureChanged();

     /**
      * A surface with Role Panel and PanelBehavior AutoHide requested to be hidden.
diff --git a/src/xdgshellwindow.cpp b/src/xdgshellwindow.cpp
index 6f3b1b8d0e..7299ed1f35 100644
--- a/src/xdgshellwindow.cpp
+++ b/src/xdgshellwindow.cpp
@@ -1696,6 +1696,13 @@ void XdgToplevelWindow::installPlasmaShellSurface(PlasmaShellSurfaceInterface *s
     connect(shellSurface, &PlasmaShellSurfaceInterface::skipSwitcherChanged, this, [this] {
         setSkipSwitcher(m_plasmaShellSurface->skipSwitcher());
     });
+
+    if (shellSurface->excludeFromCapture()) {
+        setExcludeFromCapture(true);
+    }
+    connect(shellSurface, &PlasmaShellSurfaceInterface::excludeFromCaptureChanged, this, [this] {
+        setExcludeFromCapture(m_plasmaShellSurface->excludeFromCapture());
+    });
 }

 void XdgToplevelWindow::setFullScreen(bool set)
-- 
2.53.0

From cbd19bc0c562d73509f83bbed0a18a5bbc72fe8e Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 19:06:00 +0100
Subject: [PATCH] plasmaquick: add
 PlasmaShellWaylandIntegration::setExcludeFromCapture

Plasma windows had no way to ask the compositor to keep them out of
screen recordings and screenshots. Bind plasma-shell version 9 and expose
its set_exclude_from_capture request, sent when the surface is created.

BUG: 528880
---
 .../plasmashellwaylandintegration.cpp           | 17 ++++++++++++++++-
 src/plasmaquick/plasmashellwaylandintegration.h |  8 ++++++++
 2 files changed, 24 insertions(+), 1 deletion(-)

diff --git a/src/plasmaquick/plasmashellwaylandintegration.cpp b/src/plasmaquick/plasmashellwaylandintegration.cpp
index c3af1b75c..048b43337 100644
--- a/src/plasmaquick/plasmashellwaylandintegration.cpp
+++ b/src/plasmaquick/plasmashellwaylandintegration.cpp
@@ -19,7 +19,7 @@ class PlasmaShellManager : public QWaylandClientExtensionTemplate<PlasmaShellMan
 {
 public:
     PlasmaShellManager()
-        : QWaylandClientExtensionTemplate<PlasmaShellManager>(8)
+        : QWaylandClientExtensionTemplate<PlasmaShellManager>(9)
     {
         initialize();
     }
@@ -71,6 +71,7 @@ public:
     QtWayland::org_kde_plasma_surface::role m_role = QtWayland::org_kde_plasma_surface::role_normal;
     bool m_takesFocus = false;
     bool m_openUnderCursor = false;
+    bool m_excludeFromCapture = false;
     std::unique_ptr<PlasmaShellSurface> m_shellSurface;
 };

@@ -121,6 +122,9 @@ void PlasmaShellWaylandIntegrationPrivate::surfaceCreated()
         if (m_openUnderCursor) {
             m_shellSurface->open_under_cursor();
         }
+        if (m_excludeFromCapture && m_shellSurface->version() >= ORG_KDE_PLASMA_SURFACE_SET_EXCLUDE_FROM_CAPTURE_SINCE_VERSION) {
+            m_shellSurface->set_exclude_from_capture(true);
+        }
     }
 }

@@ -228,4 +232,15 @@ void PlasmaShellWaylandIntegration::openUnderCursor()
     }
 }

+void PlasmaShellWaylandIntegration::setExcludeFromCapture(bool exclude)
+{
+    if (exclude == d->m_excludeFromCapture) {
+        return;
+    }
+    d->m_excludeFromCapture = exclude;
+    if (d->m_shellSurface && d->m_shellSurface->version() >= ORG_KDE_PLASMA_SURFACE_SET_EXCLUDE_FROM_CAPTURE_SINCE_VERSION) {
+        d->m_shellSurface->set_exclude_from_capture(exclude);
+    }
+}
+
 #include "moc_plasmashellwaylandintegration.cpp"
diff --git a/src/plasmaquick/plasmashellwaylandintegration.h b/src/plasmaquick/plasmashellwaylandintegration.h
index 99e334e86..953316ee3 100644
--- a/src/plasmaquick/plasmashellwaylandintegration.h
+++ b/src/plasmaquick/plasmashellwaylandintegration.h
@@ -68,6 +68,14 @@ public:
      */
     void openUnderCursor();

+    /*!
+     * Request that this surface is not visible in screen recordings,
+     * screen sharing and screenshots
+     *
+     * \since 6.9
+     */
+    void setExcludeFromCapture(bool exclude);
+
     bool eventFilter(QObject *watched, QEvent *event) override;

 private:
-- 
2.53.0

From 4445a8a3a6c643b9057401b038774c5fec28675a Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 19:06:00 +0100
Subject: [PATCH] applets/notifications: add option to hide popups from screen
 capture

The only way to keep notifications out of a screencast was to enable Do
Not Disturb, which made people miss them. Add a Popups option that keeps
notification popups visible on screen but excludes them from capture.

BUG: 528880
---
 applets/notifications/global/Globals.qml        |  1 +
 applets/notifications/notificationwindow.cpp    | 17 +++++++++++++++++
 applets/notifications/notificationwindow.h      |  6 ++++++
 kcms/notifications/ui/main.qml                  | 14 ++++++++++++++
 .../kcfg/notificationsettings.kcfg              |  3 +++
 libnotificationmanager/settings.cpp             | 14 ++++++++++++++
 libnotificationmanager/settings.h               | 10 ++++++++++
 7 files changed, 65 insertions(+)

diff --git a/applets/notifications/global/Globals.qml b/applets/notifications/global/Globals.qml
index 8e8e56f88d..4b79f4ff59 100644
--- a/applets/notifications/global/Globals.qml
+++ b/applets/notifications/global/Globals.qml
@@ -529,6 +529,7 @@ QtObject {

             popupWidth: globals.popupWidth
             showPopupTimeout: globals.notificationSettings.showPopupTimeout
+            excludeFromCapture: globals.notificationSettings.hidePopupsFromCapture

             isCritical: urgency === NotificationManager.Notifications.CriticalUrgency || (urgency === NotificationManager.Notifications.NormalUrgency && !globals.notificationSettings.inhibitNotificationsWhenFullscreen)

diff --git a/applets/notifications/notificationwindow.cpp b/applets/notifications/notificationwindow.cpp
index 7a8b64283d..c3286eb33d 100644
--- a/applets/notifications/notificationwindow.cpp
+++ b/applets/notifications/notificationwindow.cpp
@@ -52,6 +52,23 @@ void NotificationWindow::setIsCritical(bool critical)
     Q_EMIT isCriticalChanged();
 }

+bool NotificationWindow::excludeFromCapture() const
+{
+    return m_excludeFromCapture;
+}
+
+void NotificationWindow::setExcludeFromCapture(bool exclude)
+{
+    if (m_excludeFromCapture == exclude) {
+        return;
+    }
+
+    m_excludeFromCapture = exclude;
+    PlasmaShellWaylandIntegration::get(this)->setExcludeFromCapture(exclude);
+
+    Q_EMIT excludeFromCaptureChanged();
+}
+
 bool NotificationWindow::event(QEvent *e)
 {
     // moveEvents only occur when we have a platform window, so we need to explicitly sync on creation
diff --git a/applets/notifications/notificationwindow.h b/applets/notifications/notificationwindow.h
index 9fa96a77d9..1527851896 100644
--- a/applets/notifications/notificationwindow.h
+++ b/applets/notifications/notificationwindow.h
@@ -13,6 +13,7 @@ class NotificationWindow : public PlasmaQuick::PlasmaWindow
     QML_ELEMENT
     Q_PROPERTY(bool takeFocus READ takeFocus WRITE setTakeFocus NOTIFY takeFocusChanged)
     Q_PROPERTY(bool isCritical READ isCritical WRITE setIsCritical NOTIFY isCriticalChanged FINAL)
+    Q_PROPERTY(bool excludeFromCapture READ excludeFromCapture WRITE setExcludeFromCapture NOTIFY excludeFromCaptureChanged FINAL)
 public:
     NotificationWindow();
     ~NotificationWindow() override;
@@ -23,14 +24,19 @@ public:
     bool isCritical() const;
     void setIsCritical(bool critical);

+    bool excludeFromCapture() const;
+    void setExcludeFromCapture(bool exclude);
+
 protected:
     bool event(QEvent *e) override;
     void moveEvent(QMoveEvent *) override;
 Q_SIGNALS:
     void takeFocusChanged();
     void isCriticalChanged();
+    void excludeFromCaptureChanged();

 private:
     bool m_takeFocus = false;
     bool m_critical = false;
+    bool m_excludeFromCapture = false;
 };
diff --git a/kcms/notifications/ui/main.qml b/kcms/notifications/ui/main.qml
index 83dc77275c..e56f0563a3 100644
--- a/kcms/notifications/ui/main.qml
+++ b/kcms/notifications/ui/main.qml
@@ -314,6 +314,20 @@ KCM.SimpleKCM {
             }
         }

+        QtControls.CheckBox {
+            text: i18nc("@option:check", "Hide from screen recordings and screenshots")
+            checked: kcm.notificationSettings.hidePopupsFromCapture
+            onClicked: kcm.notificationSettings.hidePopupsFromCapture = checked
+            // Only applicable to Wayland where we can control who can capture the screen
+            visible: Qt.platform.pluginName.includes("wayland")
+
+            KCM.SettingStateBinding {
+                configObject: kcm.notificationSettings
+                settingName: "HidePopupsFromCapture"
+                extraEnabledConditions: root.notificationsAvailable
+            }
+        }
+
         Item {
             Kirigami.FormData.label: i18nc("@title:group", "Additional feedback")
             Kirigami.FormData.isSection: true
diff --git a/libnotificationmanager/kcfg/notificationsettings.kcfg b/libnotificationmanager/kcfg/notificationsettings.kcfg
index 2d5ef9081e..c05b44a303 100644
--- a/libnotificationmanager/kcfg/notificationsettings.kcfg
+++ b/libnotificationmanager/kcfg/notificationsettings.kcfg
@@ -33,6 +33,9 @@
         <entry name="ShowPopupTimeout" type="Bool">
             <default>true</default>
         </entry>
+        <entry name="HidePopupsFromCapture" type="Bool">
+            <default>false</default>
+        </entry>
     </group>

 </kcfg>
diff --git a/libnotificationmanager/settings.cpp b/libnotificationmanager/settings.cpp
index 9e0da288ab..3a32e4759d 100644
--- a/libnotificationmanager/settings.cpp
+++ b/libnotificationmanager/settings.cpp
@@ -442,6 +442,20 @@ void Settings::setShowPopupTimeout(bool show)
     d->setDirty(true);
 }

+bool Settings::hidePopupsFromCapture() const
+{
+    return d->notificationSettings.hidePopupsFromCapture();
+}
+
+void Settings::setHidePopupsFromCapture(bool hide)
+{
+    if (this->hidePopupsFromCapture() == hide) {
+        return;
+    }
+    d->notificationSettings.setHidePopupsFromCapture(hide);
+    d->setDirty(true);
+}
+
 bool Settings::jobsInNotifications() const
 {
     return d->jobSettings.inNotifications();
diff --git a/libnotificationmanager/settings.h b/libnotificationmanager/settings.h
index 82eb89d055..3629afce8d 100644
--- a/libnotificationmanager/settings.h
+++ b/libnotificationmanager/settings.h
@@ -67,6 +67,13 @@ class NOTIFICATIONMANAGER_EXPORT Settings : public QObject
      */
     Q_PROPERTY(bool showPopupTimeout READ showPopupTimeout WRITE setShowPopupTimeout NOTIFY settingsChanged)

+    /**
+     * Whether notification popups are hidden from screen recordings, screen sharing and screenshots.
+     *
+     * @since 6.9
+     */
+    Q_PROPERTY(bool hidePopupsFromCapture READ hidePopupsFromCapture WRITE setHidePopupsFromCapture NOTIFY settingsChanged)
+
     /**
      * Whether to show application jobs as notifications
      */
@@ -287,6 +294,9 @@ public:
     bool showPopupTimeout() const;
     void setShowPopupTimeout(bool show);

+    bool hidePopupsFromCapture() const;
+    void setHidePopupsFromCapture(bool hide);
+
     bool jobsInNotifications() const;
     void setJobsInNotifications(bool enable);

-- 
2.53.0
